-- +goose Up
CREATE TABLE outbox_events (
    -- Generated by Go; also used as the stable Asynq task ID.
    id text PRIMARY KEY CHECK (btrim(id) <> ''),

    asset_id text NOT NULL REFERENCES media_assets(id),

    task_type text NOT NULL CHECK (btrim(task_type) <> ''),
    queue_name text NOT NULL CHECK (btrim(queue_name) <> ''),

    -- Identifier-only input, e.g. {"assetId": "asset_123"}.
    payload jsonb NOT NULL
        CHECK (jsonb_typeof(payload) = 'object'),

    -- Prevent duplicate creation of the same logical event.
    dedupe_key text NOT NULL UNIQUE
        CHECK (btrim(dedupe_key) <> ''),

    -- Delivery attempts to Redis, not worker execution attempts.
    dispatch_attempts integer NOT NULL DEFAULT 0
        CHECK (dispatch_attempts >= 0),

    next_attempt_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Sanitized machine-readable code, not raw error text.
    last_error_code text,

    -- Redis accepted the task; processing may still be pending.
    dispatched_at timestamptz,

    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX outbox_events_pending_idx
    ON outbox_events (next_attempt_at, created_at, id)
    WHERE dispatched_at IS NULL;

-- +goose Down
-- Destructive: test only against a disposable database/schema.
DROP TABLE outbox_events;